create or replace function app_private.current_account_is_platform_admin() returns boolean language sql stable security definer set search_path=public,app_private as $$select app_private.current_account_is_owner() or exists(select 1 from public.platform_admin_memberships m join public.accounts a on a.id=m.account_id where a.auth_user_id=auth.uid() and a.status='active' and m.status='active' and m.revoked_at is null)$$;
create or replace function public.admin_context_command() returns jsonb language plpgsql security invoker set search_path=public,app_private as $$declare aid uuid; is_owner boolean; caps jsonb; roles jsonb; begin select id into aid from public.accounts where auth_user_id=auth.uid() and status='active'; if aid is null or not app_private.current_account_is_platform_admin() then raise exception 'not authorized'; end if; is_owner:=app_private.current_account_is_owner(); select coalesce(jsonb_agg(x.capability order by x.capability),'[]'::jsonb) into caps from(select distinct rc.capability from public.platform_admin_memberships m join public.platform_role_capabilities rc on rc.role_id=m.role_id where m.account_id=aid and m.status='active' and m.revoked_at is null union select g.capability from public.platform_admin_capability_grants g where g.account_id=aid and g.effect='allow' and g.revoked_at is null)x where not exists(select 1 from public.platform_admin_capability_grants d where d.account_id=aid and d.effect='deny' and d.capability=x.capability and d.revoked_at is null); select coalesce(jsonb_agg(jsonb_build_object('key',r.role_key,'name',r.display_name) order by r.display_name),'[]'::jsonb) into roles from public.platform_admin_memberships m join public.platform_roles r on r.id=m.role_id where m.account_id=aid and m.status='active' and m.revoked_at is null; return jsonb_build_object('account_id',aid,'is_owner',is_owner,'roles',roles,'capabilities',case when is_owner then caps||'["platform.owner"]'::jsonb else caps end); end$$;
grant execute on function public.admin_context_command() to authenticated;
create or replace function public.admin_access_roster_command() returns jsonb language plpgsql security invoker set search_path=public,app_private as $$begin if not app_private.current_account_has_platform_capability('platform.admin.manage') then raise exception 'not authorized'; end if; return coalesce((select jsonb_agg(row_data order by lower(coalesce(row_data->>'display_name',''))) from(select jsonb_build_object('account_id',a.id,'display_name',p.display_name,'account_status',a.status,'is_owner',o.owner_account_id is not null,'roles',coalesce((select jsonb_agg(jsonb_build_object('key',r.role_key,'name',r.display_name,'status',m.status) order by r.display_name) from public.platform_admin_memberships m join public.platform_roles r on r.id=m.role_id where m.account_id=a.id and m.revoked_at is null),'[]'::jsonb)) row_data from public.accounts a left join public.profiles p on p.account_id=a.id left join public.platform_ownership o on o.owner_account_id=a.id where o.owner_account_id is not null or exists(select 1 from public.platform_admin_memberships m where m.account_id=a.id and m.revoked_at is null))q),'[]'::jsonb); end$$;
grant execute on function public.admin_access_roster_command() to authenticated;
create or replace function public.create_platform_admin_invitation_command(p_email text,p_role_key text,p_token_hash text,p_expires_at timestamptz) returns uuid language plpgsql security invoker set search_path=public,app_private as $$declare me uuid; rid uuid; iid uuid; email_norm text; begin select id into me from public.accounts where auth_user_id=auth.uid() and status='active'; if me is null or not app_private.current_account_has_platform_capability('platform.admin.manage') then raise exception 'not authorized'; end if; if p_role_key='super_admin' and not app_private.current_account_is_owner() then raise exception 'only platform owner may invite super admin'; end if; if p_expires_at<=now() or p_expires_at>now()+interval '14 days' then raise exception 'invalid expiry'; end if; email_norm:=lower(btrim(p_email)); if email_norm='' or position('@' in email_norm)<2 then raise exception 'valid email required'; end if; select id into rid from public.platform_roles where role_key=p_role_key and is_active; if rid is null then raise exception 'role not found'; end if; update public.platform_admin_invitations set status='revoked',revoked_at=now() where email_normalized=email_norm and status='pending'; insert into public.platform_admin_invitations(email_normalized,role_id,token_hash,invited_by_account_id,expires_at) values(email_norm,rid,p_token_hash,me,p_expires_at) returning id into iid; insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,reason_code,data_classification,metadata) values(auth.uid(),'user','PLATFORM_ADMIN_INVITED','platform_admin_invitation',iid,'admin_access_change','system_internal',jsonb_build_object('role_key',p_role_key,'expires_at',p_expires_at)); return iid; end$$;
grant execute on function public.create_platform_admin_invitation_command(text,text,text,timestamptz) to authenticated;
create or replace function public.accept_platform_admin_invitation_command(p_token text) returns text language plpgsql security invoker set search_path=public,app_private,extensions as $$declare me uuid; invite public.platform_admin_invitations%rowtype; rid_key text; expected_hash text; begin select id into me from public.accounts where auth_user_id=auth.uid() and status='active'; if me is null then raise exception 'active account required'; end if; expected_hash:=encode(digest(p_token,'sha256'),'hex'); select * into invite from public.platform_admin_invitations where token_hash=expected_hash and status='pending' for update; if not found then raise exception 'invitation not found'; end if; if invite.expires_at<=now() then update public.platform_admin_invitations set status='expired' where id=invite.id; raise exception 'invitation expired'; end if; if lower(coalesce(auth.jwt()->>'email',''))<>invite.email_normalized then raise exception 'invitation email does not match signed-in account'; end if; select role_key into rid_key from public.platform_roles where id=invite.role_id; if rid_key='super_admin' and not exists(select 1 from public.platform_ownership where owner_account_id=invite.invited_by_account_id) then raise exception 'super admin invitation must originate from owner'; end if; insert into public.platform_admin_memberships(account_id,role_id,status,granted_by_account_id,reason) values(me,invite.role_id,'active',invite.invited_by_account_id,'accepted invitation') on conflict(account_id,role_id) do update set status='active',granted_by_account_id=excluded.granted_by_account_id,granted_at=now(),revoked_at=null,revoked_by_account_id=null,reason='accepted invitation'; update public.platform_admin_invitations set status='accepted',accepted_by_account_id=me,accepted_at=now() where id=invite.id; insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,reason_code,data_classification,metadata) values(auth.uid(),'user','PLATFORM_ADMIN_INVITATION_ACCEPTED','account',me,'admin_access_change','system_internal',jsonb_build_object('invitation_id',invite.id,'role_key',rid_key)); return rid_key; end$$;
grant execute on function public.accept_platform_admin_invitation_command(text) to authenticated;
create or replace function public.revoke_platform_admin_invitation_command(p_invitation_id uuid,p_reason text) returns void language plpgsql security invoker set search_path=public,app_private as $$begin if not app_private.current_account_has_platform_capability('platform.admin.manage') then raise exception 'not authorized'; end if; update public.platform_admin_invitations set status='revoked',revoked_at=now() where id=p_invitation_id and status='pending'; insert into public.audit_events(actor_user_id,actor_type,action,resource_type,resource_id,reason_code,data_classification,metadata) values(auth.uid(),'user','PLATFORM_ADMIN_INVITATION_REVOKED','platform_admin_invitation',p_invitation_id,'admin_access_change','system_internal',jsonb_build_object('reason',p_reason)); end$$;
grant execute on function public.revoke_platform_admin_invitation_command(uuid,text) to authenticated;
create policy profiles_admin_manage_read on public.profiles for select to authenticated using(app_private.current_account_has_platform_capability('platform.admin.manage'));
create policy accounts_admin_manage_read on public.accounts for select to authenticated using(app_private.current_account_has_platform_capability('platform.admin.manage'));
